-- Xmip Storage on MariaDB: the runtime database's schema.
--
-- Generated by xmip-core-persist (storage::schema), the definition the
-- backend reads and writes by; do not edit. `cargo test --test database`
-- at the estate root fails when this file differs from what it writes.
-- What to run, in what order and why: README.md beside this file.
--
-- Run as root with the mariadb client.

USE `xmip_runtime`;

-- each schema version the database has held, the one it was made at and each an upgrade reached, with when; the version it holds is the highest.
CREATE TABLE `schema_version` (
    `version` int NOT NULL,
    `recorded_at` datetime(6) NOT NULL,
    CONSTRAINT schema_version_key PRIMARY KEY (`version`)
) ENGINE=InnoDB;

-- every Stream, once, as written and never changed: its length, its chunks and the SHA-256 digest of its bytes; a chunk and every Message referring to it refer to it by its identifier.
CREATE TABLE `stream` (
    `stream` binary(16) NOT NULL,
    `length` bigint NOT NULL,
    `chunks` int NOT NULL,
    `digest` longblob NOT NULL,
    `written_at` datetime(6) NOT NULL,
    CONSTRAINT stream_key PRIMARY KEY (`stream`)
) ENGINE=InnoDB;

-- every Stream's chunks, by its identifier and their number; a Stream ends where it has no further chunk.
CREATE TABLE `stream_chunk` (
    `stream` binary(16) NOT NULL,
    `chunk` int NOT NULL,
    `bytes` longblob NOT NULL,
    CONSTRAINT stream_chunk_key PRIMARY KEY (`stream`, `chunk`)
) ENGINE=InnoDB;

-- every Message, as a step wrote it, every single value of it in a column of its own.
CREATE TABLE `message` (
    `message` binary(16) NOT NULL,
    `body` longblob NOT NULL,
    `created_at` datetime(6) NOT NULL,
    `previous_message` binary(16) NULL,
    `generation` int NOT NULL,
    `created_by` varchar(32) NOT NULL,
    `priority` varchar(32) NOT NULL,
    `execution_profile` varchar(32) NOT NULL,
    `durability` varchar(32) NOT NULL,
    `size_bytes` bigint NOT NULL,
    `party` varchar(400) NULL,
    `contract` varchar(400) NULL,
    `stream` binary(16) NULL,
    CONSTRAINT message_key PRIMARY KEY (`message`)
) ENGINE=InnoDB;

CREATE INDEX `message_created` ON `message` (`created_at`);

CREATE INDEX `message_party` ON `message` (`party`, `created_at`);

CREATE INDEX `message_contract` ON `message` (`contract`, `created_at`);

CREATE INDEX `message_previous` ON `message` (`previous_message`);

CREATE INDEX `message_stream` ON `message` (`stream`);

-- every Journey, as a step wrote it, every single value of it in a column of its own.
CREATE TABLE `journey` (
    `journey` binary(16) NOT NULL,
    `body` longblob NOT NULL,
    `created_at` datetime(6) NOT NULL,
    `updated_at` datetime(6) NOT NULL,
    `state` varchar(32) NOT NULL,
    `previous_journey` binary(16) NULL,
    `subscription` varchar(400) NULL,
    `cause_work_process` varchar(400) NULL,
    `depth` int NOT NULL,
    `work_process` varchar(400) NULL,
    `send_port` varchar(400) NULL,
    `send_location` int NOT NULL,
    `attempts` int NOT NULL,
    `message` binary(16) NULL,
    `origin` binary(16) NULL,
    `open` boolean NOT NULL,
    `group_delivery` binary(16) NULL,
    `group_open` boolean NOT NULL,
    CONSTRAINT journey_key PRIMARY KEY (`journey`)
) ENGINE=InnoDB;

CREATE INDEX `journey_state` ON `journey` (`state`, `updated_at`);

CREATE INDEX `journey_send_port` ON `journey` (`send_port`, `state`);

CREATE INDEX `journey_previous` ON `journey` (`previous_journey`);

CREATE INDEX `journey_message` ON `journey` (`message`);

-- the Journeys a paused Subscription holds, at their place in its queue, each once.
CREATE TABLE `held` (
    `queue` binary(16) NOT NULL,
    `sequence` bigint NOT NULL,
    `journey` binary(16) NOT NULL,
    `body` longblob NOT NULL,
    `held_at` datetime(6) NOT NULL,
    `failed` boolean NOT NULL,
    `due_at` datetime(6) NOT NULL,
    CONSTRAINT held_key PRIMARY KEY (`queue`, `sequence`),
    CONSTRAINT held_unique UNIQUE (`queue`, `journey`)
) ENGINE=InnoDB;

CREATE INDEX `held_time` ON `held` (`queue`, `held_at`);

CREATE INDEX `held_due` ON `held` (`queue`, `failed`, `due_at`, `sequence`);

-- each queue's first place, its next and how many it holds.
CREATE TABLE `held_places` (
    `queue` binary(16) NOT NULL,
    `first_place` bigint NOT NULL,
    `next_place` bigint NOT NULL,
    `held` bigint NOT NULL,
    CONSTRAINT held_places_key PRIMARY KEY (`queue`)
) ENGINE=InnoDB;

-- each queue's places in the order its Journeys are due: the place no Journey due since it was held is before, the due time and place no retry is before, and how many keep a retry's due time.
CREATE TABLE `held_due_places` (
    `queue` binary(16) NOT NULL,
    `first_due_place` bigint NOT NULL,
    `first_retry_at` datetime(6) NOT NULL,
    `first_retry_place` bigint NOT NULL,
    `retrying` bigint NOT NULL,
    CONSTRAINT held_due_places_key PRIMARY KEY (`queue`)
) ENGINE=InnoDB;

-- the Messages that failed waiting in each Send Port's queue for an operator, in the order they failed, each once, with its place in the queue and why, written with the failure and taken out with the operator's act.
CREATE TABLE `failed_message` (
    `queue` binary(16) NOT NULL,
    `sequence` bigint NOT NULL,
    `journey` binary(16) NOT NULL,
    `place` bigint NOT NULL,
    `reason` longtext NOT NULL,
    `failed_at` datetime(6) NOT NULL,
    CONSTRAINT failed_message_key PRIMARY KEY (`queue`, `sequence`),
    CONSTRAINT failed_message_unique UNIQUE (`queue`, `journey`)
) ENGINE=InnoDB;

-- each queue's index of failed Messages: its first place, its next and how many failed Messages wait in the queue.
CREATE TABLE `failed_message_places` (
    `queue` binary(16) NOT NULL,
    `first_place` bigint NOT NULL,
    `next_place` bigint NOT NULL,
    `failed` bigint NOT NULL,
    CONSTRAINT failed_message_places_key PRIMARY KEY (`queue`)
) ENGINE=InnoDB;

-- each node's Dead Message Queue: every Message nothing matched, at its place, with its receive context, what its gates concluded, its promoted properties and each Subscription's reason for declining, each once.
CREATE TABLE `dead_message` (
    `queue` binary(16) NOT NULL,
    `sequence` bigint NOT NULL,
    `message` binary(16) NOT NULL,
    `body` longblob NOT NULL,
    `stream` binary(16) NOT NULL,
    `node` varchar(400) NOT NULL,
    `receive_location` varchar(400) NOT NULL,
    `queued_at` datetime(6) NOT NULL,
    CONSTRAINT dead_message_key PRIMARY KEY (`queue`, `sequence`),
    CONSTRAINT dead_message_unique UNIQUE (`queue`, `message`)
) ENGINE=InnoDB;

CREATE INDEX `dead_message_time` ON `dead_message` (`queue`, `queued_at`);

-- each Dead Message Queue's first place, its next and how many it holds.
CREATE TABLE `dead_message_places` (
    `queue` binary(16) NOT NULL,
    `first_place` bigint NOT NULL,
    `next_place` bigint NOT NULL,
    `held` bigint NOT NULL,
    CONSTRAINT dead_message_places_key PRIMARY KEY (`queue`)
) ENGINE=InnoDB;

-- each Message replayed from a Dead Message Queue, so a Replay asked again writes nothing twice.
CREATE TABLE `dead_message_replayed` (
    `queue` binary(16) NOT NULL,
    `message` binary(16) NOT NULL,
    CONSTRAINT dead_message_replayed_key PRIMARY KEY (`queue`, `message`)
) ENGINE=InnoDB;

-- each Message published, with the digest of its Publication, so a Publication asked again writes nothing and resets no Journey moved on since.
CREATE TABLE `publication` (
    `message` binary(16) NOT NULL,
    `digest` longblob NOT NULL,
    CONSTRAINT publication_key PRIMARY KEY (`message`)
) ENGINE=InnoDB;

-- the claim on each Journey: its holder, its token, when it lapses, and whether it was given back or its step handed on.
CREATE TABLE `claim` (
    `journey` binary(16) NOT NULL,
    `holder` varchar(400) NOT NULL,
    `token` binary(16) NOT NULL,
    `until_unix_nanos` bigint NOT NULL,
    `released` boolean NOT NULL,
    `handed_on` boolean NOT NULL,
    CONSTRAINT claim_key PRIMARY KEY (`journey`)
) ENGINE=InnoDB;

-- audit records as first written, until the audit keeper moves them.
CREATE TABLE `audit` (
    `sequence` bigint AUTO_INCREMENT NOT NULL,
    `id` binary(16) NOT NULL,
    `body` longblob NOT NULL,
    CONSTRAINT audit_key PRIMARY KEY (`sequence`)
) ENGINE=InnoDB;

-- The schema version it holds now.
INSERT INTO `schema_version` (`version`, `recorded_at`) VALUES (1, UTC_TIMESTAMP(6));

GRANT SELECT, INSERT, UPDATE, DELETE ON `xmip_runtime`.* TO 'xmip_storage'@'%';
